\boxed{f(x, y) = x e^{\cos y} + \frac{x^2}{2}}
\begin{itemize}
    \item 求偏导数
    \begin{align*} \label{eq:1} f_x &= e^{\cos y} + x \sin y \\ f_y &= x e^{\cos y} \cdot (-\sin y) + 0 = -x e^{\cos y} \sin y\end{align*}
    \item 求驻点
    \begin{align*} f_x &= 0 \implies e^{\cos y} + x \sin y = 0 \\ f_y &= 0 \implies -x e^{\cos y} \sin y = 0\end{align*}
    由 $f_y = 0$ 可得 $x = 0$ 或 $\sin y = 0$。
    \begin{itemize}
        \item 若 $x = 0$，则 $e^{\cos y} = 0$，这不可能。
        \item 若 $\sin y = 0$，则 $y = k \pi$，$k \in \mathbb{Z}$。
        \begin{itemize}
            \item 若 $y = 0$，则 $f(0, 0) = 0$。
            \item 若 $y = \pi$，则 $f(0, \pi) = 0$。
        \end{itemize}
    \end{itemize}
    \item 检验驻点
